export const moreDocuments: typeof documents = [
  { slug: "guide-hoi-an-two-days", title: "Hoi An in two days", dest: "hoi-an", category: "guide", source: E,
    content: "Spend the first morning in Hoi An Ancient Town before the heat and the tour groups arrive, visiting the Japanese Covered Bridge and one or two assembly halls on the shared heritage ticket. Take a cooking class or visit Tra Que Vegetable Village in the afternoon. In the evening walk the lantern-lit lanes and float a paper lantern on the river. On the second day cycle to An Bang Beach for breakfast and swimming, then try cao lau noodles for lunch. Tailors can make clothes in a day or two; agree measurements and price first and allow time for fittings. My Son Sanctuary is best visited early in the morning." },
  { slug: "faq-vietnam-crossing-sim", title: "Vietnam practical FAQ: crossing streets, SIM cards and money", category: "faq", source: E,
    content: "How do I cross the street? Walk slowly and steadily; motorbikes flow around you. Never run or stop suddenly. Which currency is used? Vietnamese dong; cards are accepted in hotels and larger restaurants, but street stalls take cash. Can I buy a SIM card? Yes, at the airport or at a phone shop with your passport. Which ride-hailing app works best? Grab operates in the main cities and shows the price before you ride. Is tap water safe? Drink bottled or filtered water." },
  { slug: "guide-da-nang-hoi-an-combo", title: "Combining Da Nang and Hoi An", dest: "da-nang", category: "guide", source: E,
    content: "Da Nang suits beach days and families; Hoi An suits slow evenings and food. Many travellers base themselves in one and day-trip to the other because the two are only about 30 minutes apart by road. Ba Na Hills and the Marble Mountains are easiest from Da Nang, while My Son Sanctuary is closer to Hoi An. The Hai Van Pass is a scenic drive between Da Nang and Hue if you have an extra day. Typhoon season is roughly September to November, so check forecasts and keep your plans flexible." },
  { slug: "guide-phuket-first-timer", title: "Phuket first-timer guide", dest: "phuket", category: "guide", source: E,
    content: "Phuket is large and distances add up, so choose one or two beaches as a base. Patong is lively and busy; Kata and Karon are calmer and good for families; the north and west are quieter. Use Grab or Bolt for fair prices and book boat trips to Phang Nga Bay a day ahead. In the monsoon season from May to October the sea can be dangerous. Follow lifeguard flags and never swim at beaches marked with red flags. Old Town is best in the late afternoon when the weekend walking street opens." },
  { slug: "guide-krabi-islands", title: "Krabi beaches and islands", dest: "krabi", category: "guide", source: E,
    content: "Railay and Phra Nang can only be reached by longtail boat from Ao Nang or Krabi Town, usually taking 15 minutes. Boats leave when full and tides can affect landings. Four Islands trips visit Koh Poda, Chicken Island and Tup Island and run most days of the dry season. Bring reef-safe sunscreen and a waterproof bag. The Tiger Cave Temple has more than a thousand steps; start early and carry water. Ao Thalane kayaking is best on the rising tide." },
  { slug: "guide-penang-food-trail", title: "Penang food trail", dest: "penang", category: "guide", source: E,
    content: "Penang is known as Malaysia's food capital. Start with char kway teow, assam laksa and cendol at hawker stalls on Chulia Street and Gurney Drive. Many stalls close by early afternoon or sell out, so go early. Nyonya kueh and Peranakan curries are best tried in older teahouses. Carry cash. Street food is generally safe at busy stalls with high turnover. For a rest from the heat, take the funicular up Penang Hill in the late afternoon." },
  { slug: "guide-kyoto-temples-early", title: "Kyoto temples without the crowds", dest: "kyoto", category: "guide", source: E,
    content: "Visit Fushimi Inari at sunrise and Kiyomizu-dera at opening. Arashiyama Bamboo Grove is quietest before 8 am. Kinkaku-ji is best in the early morning when the sun lights the gold leaf. Use the bus day pass or an IC card, and avoid taxis at rush hour. Spring blossom in late March and April and autumn colour in November are the busiest times; book accommodation months ahead. In Gion, do not enter private lanes marked as no photography and never chase geiko or maiko for pictures." },
  { slug: "etiquette-japan", title: "Etiquette in Japan", dest: "kyoto", category: "etiquette", source: E,
    content: "Remove your shoes in homes, ryokan and some restaurants. Do not tip: good service is expected and tipping can confuse staff. Keep your voice low on trains and avoid eating while walking in busy areas. Carry some cash for shrines and small shops. Bow lightly when greeting. At onsen wash before you enter the bath and tie long hair up; tattoos may be restricted at some baths." },
  { slug: "guide-yogyakarta-temples", title: "Borobudur and Prambanan guide", dest: "yogyakarta", category: "guide", source: E,
    content: "Borobudur is about an hour from Yogyakarta and limits the number of visitors who can climb the upper platforms; book through the official ticket channel in advance. Sunrise tours leave very early, so wear layers. Prambanan is closer to the airport and lit beautifully at dusk, when a Ramayana ballet is sometimes staged. Wear modest clothing and a sarong where required. Plan the temples on different days, because heat and distances add up." },
  { slug: "guide-vientiane-slow", title: "Vientiane at a gentle pace", dest: "vientiane", category: "guide", source: E,
    content: "Vientiane rewards slow wandering. Start at Pha That Luang in the morning light, then walk down to Wat Si Saket and the Patuxai arch. Buddha Park is a short ride out of town. Keep the evening for the riverside night market and a cold drink at sunset. The COPE Visitor Centre is an essential, moving stop to understand the legacy of unexploded ordnance. Many shops close in the middle of the day, so plan your errands in the morning." },
  { slug: "guide-ratanakiri-trekking", title: "Ratanakiri trekking and waterfalls", dest: "ratanakiri", category: "guide", source: E,
    content: "Banlung is the base for Yaklom Lake, Ka Tieng, Cha Ong and Kachanh waterfalls. Hire a motorbike only if you are experienced; red dirt roads are slippery after rain. Treks to Virachey National Park require a licensed guide and a permit, so book through a local operator. Waterfalls are strongest between June and October. When visiting villages, ask permission before taking photographs and consider buying local crafts. Bring insect repellent, water and sturdy shoes." },
  { slug: "guide-kampong-cham-bridge", title: "Kampong Cham and the bamboo bridge", dest: "kampong-cham", category: "guide", source: E,
    content: "The bamboo bridge to Koh Paen is rebuilt every dry season, usually from about November to May. Cyclists and pedestrians can cross for a small fee, and a ferry is used when the bridge is down. Wat Nokor, on the edge of town, combines a Khmer sandstone temple with a living pagoda. Cycle the flat island loop in the morning before the heat. Minibuses to Phnom Penh take about three hours." },
  { slug: "guide-mondulkiri-ethical-elephants", title: "Ethical elephant visits in Mondulkiri", dest: "mondulkiri", category: "guide", source: E,
    content: "Choose sanctuaries that prohibit riding and do not use hooks or chains. Visits typically involve feeding, walking alongside and bathing rescued elephants. Book in advance because group sizes are small. Wear clothes that can get muddy and bring a change of clothes. Mornings are cool and the highlands are cooler than the lowlands, so pack a light jacket." },
  { slug: "guide-kratie-dolphins", title: "Seeing Irrawaddy dolphins in Kratie", dest: "kratie", category: "guide", source: E,
    content: "Boats from Kampi usually take visitors to deep pools where the dolphins surface to breathe. Sightings are common but never guaranteed. Early morning and late afternoon are best. The boat trip lasts about an hour. Keep voices low and avoid chasing the animals. Stay overnight on Koh Trong island for a quiet homestay and sunset bicycle rides." },
  { slug: "faq-cambodia-festivals", title: "Cambodian festivals and holidays", category: "faq", source: E,
    content: "Khmer New Year falls in mid-April and many businesses close for three days. Pchum Ben in September or October honours ancestors, and the Water Festival (Bon Om Touk) in November is celebrated with boat races on the river in Phnom Penh. Expect crowded transport and higher hotel prices at these times, so book early. Pagoda ceremonies are an important part of festivals; dress modestly and observe quietly." },
  { slug: "guide-angkor-sunrise", title: "Angkor Wat sunrise tips", dest: "siem-reap", category: "guide", source: E,
    content: "The sunrise starts around 5:00 am and visitors gather by the reflecting pond. Arrive early for a spot, bring a torch, and expect crowds. A quieter alternative is to catch sunrise at Pre Rup or Srah Srang. After sunrise, explore the temple's galleries before the heat and crowds build. Tickets must be bought in person at the official ticket centre; remember to carry your pass each day." },
  { slug: "guide-phnom-penh-food", title: "Phnom Penh food guide", dest: "phnom-penh", category: "guide", source: E,
    content: "Try fish amok, lok lak, kuy teav noodle soup and num pang sandwiches. Street breakfast spots open before dawn and often close by mid-morning. Evening food courts around Riverside and the Russian Market offer grilled meats and fresh coconut. Bring small notes. Cafes in the BKK1 area serve specialty coffee and brunch dishes." },
  { slug: "faq-sim-wifi-sea", title: "SIM cards and Wi-Fi in Southeast Asia", category: "faq", source: E,
    content: "Tourist SIM cards or eSIMs are cheap and available at airports and phone shops. Bring your passport to register a physical SIM. Wi-Fi is common in hotels and cafes, but speeds vary. Download offline maps before long trips. Many ride-hailing apps work across the region and display fares upfront." },
  { slug: "guide-packing-tropics", title: "Packing for tropical trips", category: "guide", source: E,
    content: "Pack lightweight, quick-drying clothing, a rain jacket for the green season, sun protection, insect repellent and a refillable water bottle. Carry modest clothing for temples: shoulders and knees covered. A small day bag, a power bank and a copy of your passport are useful. Comfortable walking sandals or shoes are better than new ones. Leave space for souvenirs." },
  { slug: "faq-best-time-sea", title: "When is the best time to visit Southeast Asia?", category: "faq", source: E,
    content: "Most of mainland Southeast Asia is driest and coolest from November to February, which is also the busiest time. The hot season runs March to May with heat peaking in April. The green or rainy season from June to October brings lush landscapes, fewer tourists and lower prices, with short afternoon downpours. Southern Thailand's Andaman coast is best from November to April, while central Vietnam is driest from February to May. Check typhoon and monsoon forecasts before booking." },
  { slug: "guide-budget-asia", title: "Budget travel across Asia", category: "guide", source: E,
    content: "Daily budgets vary widely: Cambodia, Laos and Vietnam are inexpensive; Thailand and Malaysia are moderate; Singapore, Japan and South Korea are higher. Eating at local stalls, using public transport and booking free-cancellation rooms keeps costs down. Large attractions and island tours are the main expenses. Carry a card with no foreign-transaction fee and withdraw cash in larger amounts to reduce ATM fees." },
];

